// ProcessOrderPayment is the resolver for the processOrderPayment field.
func (r *mutationResolver) ProcessOrderPayment(ctx context.Context, orderID int, paymentMethod model.PaymentMethod) (*models.Transaction, error) {
	authUser, err := middlewares.RequireAuth(ctx)
	if err != nil {
		return nil, err
	}

	// Get order
	order, err := r.Resolver.OrderService.GetOrderByID(uint(orderID))
	if err != nil {
		return nil, err
	}

	// Verify user owns the order
	if order.CustomerID != authUser.UserID {
		return nil, middlewares.ErrUnauthorized
	}

	// Check if already paid
	if order.PaymentStatus == "PAID" {
		return nil, errors.New("order already paid")
	}

	// Create transaction
	oid := uint(orderID)
	transaction := &models.Transaction{
		UserID:        authUser.UserID,
		OrderID:       &oid,
		TransactionID: generateTransactionID(),
		Type:          "ORDER_PAYMENT",
		Amount:        order.TotalPrice,
		Currency:      "INR",
		PaymentMethod: string(paymentMethod),
		Status:        "SUCCESS",
	}

	// Get current balance
	balance, _ := r.Resolver.PaymentService.GetWalletBalance(authUser.UserID)
	transaction.BalanceBefore = balance

	if paymentMethod == "WALLET" {
		if balance < order.TotalPrice {
			return nil, errors.New("insufficient wallet balance")
		}
		transaction.BalanceAfter = balance - order.TotalPrice
	} else {
		transaction.BalanceAfter = balance
	}

	now := time.Now()
	transaction.ProcessedAt = &now

	if err := db.DB.Create(transaction).Error; err != nil {
		return nil, err
	}

	// Update order payment status
	db.DB.Model(order).Updates(map[string]interface{}{
		"payment_status": "PAID",
		"paid_at":        now,
		"payment_id":     transaction.TransactionID,
	})

	// If wallet payment, deduct from balance
	if paymentMethod == "WALLET" {
		db.DB.Model(&models.User{}).
			Where("id = ?", authUser.UserID).
			Update("wallet_balance", balance-order.TotalPrice)
	}

	return transaction, nil
}

// RequestRefund is the resolver for the requestRefund field.
func (r *mutationResolver) RequestRefund(ctx context.Context, orderID int, reason string) (*models.Transaction, error) {
	authUser, err := middlewares.RequireAuth(ctx)
	if err != nil {
		return nil, err
	}

	order, err := r.Resolver.OrderService.GetOrderByID(uint(orderID))
	if err != nil {
		return nil, err
	}

	if order.CustomerID != authUser.UserID {
		return nil, middlewares.ErrUnauthorized
	}

	if order.Status != "CANCELLED" {
		return nil, errors.New("can only refund cancelled orders")
	}

	if order.PaymentStatus != "PAID" {
		return nil, errors.New("order not paid")
	}

	// Calculate refund amount
	refundAmount := order.CalculateRefundAmount()

	oid := uint(orderID)
	transaction := &models.Transaction{
		UserID:        authUser.UserID,
		OrderID:       &oid,
		TransactionID: generateTransactionID(),
		Type:          "REFUND",
		Amount:        refundAmount,
		Currency:      "INR",
		PaymentMethod: order.PaymentMethod,
		Status:        "SUCCESS",
		Description:   reason,
	}

	balance, _ := r.Resolver.PaymentService.GetWalletBalance(authUser.UserID)
	transaction.BalanceBefore = balance
	transaction.BalanceAfter = balance + refundAmount

	now := time.Now()
	transaction.ProcessedAt = &now

	if err := db.DB.Create(transaction).Error; err != nil {
		return nil, err
	}

	// Update order
	db.DB.Model(order).Updates(map[string]interface{}{
		"payment_status":             "REFUNDED",
		"refunded_at":                now,
		"refund_transaction_id":      transaction.TransactionID,
		"cancellation_refund_amount": refundAmount,
	})

	// Add to wallet
	db.DB.Model(&models.User{}).
		Where("id = ?", authUser.UserID).
		Update("wallet_balance", balance+refundAmount)

	return transaction, nil
}

