// MyCaptainEarnings is the resolver for the myCaptainEarnings field.
func (r *queryResolver) MyCaptainEarnings(ctx context.Context, startDate time.Time, endDate time.Time) (*model.EarningsSummary, error) {
	authUser, err := middlewares.RequireRole(ctx, RoleCaptain)
	if err != nil {
		return nil, err
	}

	var earnings []models.CaptainEarnings
	if err := db.DB.Where("captain_id = ? AND date >= ? AND date <= ?", authUser.UserID, startDate, endDate).
		Find(&earnings).Error; err != nil {
		return nil, err
	}

	// Aggregate totals
	summary := &model.EarningsSummary{
		TotalEarnings:   0,
		NetEarnings:     0,
		TipsReceived:    0,
		BonusEarnings:   0,
		TotalOrders:     0,
		CompletedOrders: 0,
		TotalDistance:   0,
	}

	for _, e := range earnings {
		summary.TotalEarnings += e.TotalEarnings
		summary.NetEarnings += e.NetEarnings
		summary.TipsReceived += e.TipsReceived
		summary.BonusEarnings += e.BonusEarnings
		summary.TotalOrders += e.TotalOrders
		summary.CompletedOrders += e.CompletedOrders
		summary.TotalDistance += e.TotalDistance
	}

	return summary, nil
}

